ALTER TABLE "app"."content_replicas" ADD CONSTRAINT "content_replicas_ciphertext_canonical" CHECK (length("app"."content_replicas"."ciphertext") % 4 = 0 or (length("app"."content_replicas"."ciphertext") % 4 = 2 and right("app"."content_replicas"."ciphertext", 1) ~ '^[AQgw]$') or (length("app"."content_replicas"."ciphertext") % 4 = 3 and right("app"."content_replicas"."ciphertext", 1) ~ '^[AEIMQUYcgkosw048]$'));